import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Footer from '../../UI/Footer/Footer';

import img1 from '../../../assets/charity_walk.png';
import img2 from '../../../assets/cook-off.png';
import img3 from '../../../assets/talent.png';

const allEvents = [
  {
    title: 'Sports day',
    description:
      'Celebrate Sports Day on June 15 in Seychelles with exciting games, teamwork, and community',
    date: 'June 15, 2025',
    status: 'upcoming',
    image: img1,
    link: 'upcoming_event.html',
  },
  {
    title: 'Navratri',
    description:
      'Celebrate Navratri with vibrant dances, devotion, and cultural unity honoring the divine feminine.',
    date: 'June 25, 2025',
    status: 'completed',
    image: img2,
  },
  {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
    {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: img3,
  },
];

const statusClasses = {
  upcoming: 'bg-blue-100 text-blue-500',
  completed: 'bg-orange-100 text-orange-500',
  ongoing: 'bg-yellow-100 text-yellow-600',
};

const EventsPage = () => {
  const navigate = useNavigate();
  const [filter, setFilter] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const eventsPerPage = 6;

  const filteredEvents = allEvents.filter((event) => {
    const matchesFilter =
      filter === 'All'
        ? true
        : filter === 'Upcoming'
        ? event.status === 'upcoming' || event.status === 'ongoing'
        : event.status === 'completed';

    const matchesSearch =
      event.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      event.description.toLowerCase().includes(searchTerm.toLowerCase());

    return matchesFilter && matchesSearch;
  });

  const totalPages = Math.ceil(filteredEvents.length / eventsPerPage);
  const paginatedEvents = filteredEvents.slice(
    (currentPage - 1) * eventsPerPage,
    currentPage * eventsPerPage
  );

  const filterOptions = ['All', 'Upcoming', 'Past'];

  return (
    <>
      <div className="bg-white text-gray-800 font-sans min-h-screen m">
        {/* Back Button */}
        <div className="p-6">
          <button
            className="border rounded-full px-4 py-1 text-sm hover:bg-gray-100"
            onClick={() => navigate(-1)}
          >
            ⬅ Back To Home
          </button>
        </div>

        {/* Header */}
        <section className="text-center px-4">
          <h2 className="text-4xl font-bold mb-2">Our Events</h2>
          <p className="text-gray-600 max-w-xl mx-auto mb-6">
            Stay connected with our vibrant community. Discover celebrations,
            gatherings, and learning opportunities.
          </p>

          {/* Filter Buttons */}
          <div className="flex flex-wrap justify-center gap-4 mb-6">
            {filterOptions.map((label) => (
              <button
                key={label}
                onClick={() => {
                  setFilter(label);
                  setCurrentPage(1);
                }}
                className={`px-4 py-2 rounded-full text-sm transition ${
                  filter === label
                    ? 'bg-orange-500 text-white'
                    : 'text-gray-700 hover:bg-gray-100'
                }`}
              >
                {label}
              </button>
            ))}
          </div>

          {/* Search Bar */}
          <div className="mb-10 max-w-md mx-auto">
            <input
              type="text"
              placeholder="Search events..."
              value={searchTerm}
              onChange={(e) => {
                setSearchTerm(e.target.value);
                setCurrentPage(1);
              }}
              className="w-full border px-4 py-2 rounded shadow-sm focus:outline-none focus:ring-2 focus:ring-orange-300"
            />
          </div>

          {/* Events Grid */}
          <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
            {paginatedEvents.map((event, idx) => {
              const StatusTag = (
                <span
                  className={`px-2 py-0.5 rounded text-xs ${
                    statusClasses[event.status] || ''
                  }`}
                >
                  {event.status.charAt(0).toUpperCase() + event.status.slice(1)}
                </span>
              );

              const CardContent = (
                <div className="bg-white rounded shadow p-4 text-left hover:shadow-lg transition duration-200">
                  <img
                    src={event.image}
                    alt="Event"
                    className="rounded mb-4 w-full h-40 object-cover"
                  />
                  <h3 className="font-bold text-sm mb-1">{event.title}</h3>
                  <p className="text-sm text-gray-600">{event.description}</p>
                  <div className="flex justify-between items-center text-xs mt-3">
                    <span className="flex items-center gap-1">📅 {event.date}</span>
                    {StatusTag}
                  </div>
                </div>
              );

              return event.link ? (
                <a href={event.link} key={idx}>
                  {CardContent}
                </a>
              ) : (
                <div key={idx}>{CardContent}</div>
              );
            })}
          </div>

          {/* Pagination */}
          <div className="mt-10 flex justify-center gap-2">
            {[...Array(totalPages)].map((_, index) => (
              <button
                key={index + 1}
                onClick={() => setCurrentPage(index + 1)}
                className={`px-3 py-1 border rounded ${
                  currentPage === index + 1 ? 'bg-orange-500 text-white' : ''
                }`}
              >
                {index + 1}
              </button>
            ))}
          </div>
        </section>
      </div>
      <Footer />
    </>
  );
};

export default EventsPage;
